/* Focused regression harness for the NMVpnPluginInfo finalize() NULL-safety fix.
 *
 * The candidate fix replaces an unconditional g_hash_table_unref(priv->keys)
 * with nm_g_hash_table_unref(priv->keys). nm_g_hash_table_unref is an inline
 * helper defined in the target tree; this harness #includes the helper text
 * extracted verbatim from the candidate checkout by the driving shell script.
 *
 * It links against the installed GLib runtime (libglib-2.0.so.0, 2.72.4) and
 * probes the security invariant directly:
 *   - negative/vulnerable path: unconditional unref of NULL -> GLib CRITICAL
 *   - fixed path: NULL-safe wrapper on NULL -> no CRITICAL
 *   - positive control: NULL-safe wrapper on a valid table -> no CRITICAL
 */
#include <stdio.h>
#include <string.h>

typedef struct _GHashTable GHashTable;
typedef unsigned int (*HashFunc)(const void *);
typedef int (*EqualFunc)(const void *, const void *);

extern GHashTable *g_hash_table_new(HashFunc hash_func, EqualFunc key_equal_func);
extern void        g_hash_table_unref(GHashTable *hash_table);
extern unsigned int g_str_hash(const void *v);
extern int          g_str_equal(const void *v1, const void *v2);
extern unsigned int g_log_set_handler(const char *log_domain,
                                      unsigned int log_levels,
                                      void (*log_func)(const char *, unsigned int,
                                                       const char *, void *),
                                      void *user_data);

#define G_LOG_LEVEL_CRITICAL (1u << 3)
#define G_LOG_DOMAIN "GLib"

static int critical_count = 0;

static void
log_handler(const char *log_domain, unsigned int log_level,
            const char *message, void *user_data)
{
    (void) log_domain;
    (void) message;
    (void) user_data;
    if (log_level & G_LOG_LEVEL_CRITICAL)
        critical_count++;
}

/* nm_g_hash_table_unref extracted verbatim from the candidate target tree. */
#include "nm_helper.inc"

int
main(void)
{
    int failures = 0;

    g_log_set_handler(G_LOG_DOMAIN, G_LOG_LEVEL_CRITICAL, log_handler, NULL);

    /* Negative path: vulnerable unconditional unref of a NULL table. */
    critical_count = 0;
    g_hash_table_unref(NULL);
    printf("vulnerable g_hash_table_unref(NULL): criticals=%d\n", critical_count);
    if (critical_count < 1) {
        printf("FAIL: expected a GLib CRITICAL from unconditional unref of NULL\n");
        failures++;
    }

    /* Fixed path: NULL-safe wrapper on a partially-initialized (NULL) table. */
    critical_count = 0;
    nm_g_hash_table_unref(NULL);
    printf("fixed nm_g_hash_table_unref(NULL): criticals=%d\n", critical_count);
    if (critical_count != 0) {
        printf("FAIL: NULL-safe wrapper emitted a GLib CRITICAL\n");
        failures++;
    }

    /* Positive control: a valid table is still destroyed without critical. */
    critical_count = 0;
    {
        GHashTable *h = g_hash_table_new(g_str_hash, g_str_equal);
        nm_g_hash_table_unref(h);
    }
    printf("fixed nm_g_hash_table_unref(valid): criticals=%d\n", critical_count);
    if (critical_count != 0) {
        printf("FAIL: destroying a valid table emitted a GLib CRITICAL\n");
        failures++;
    }

    if (failures == 0)
        printf("RESULT: PASS (invariant holds)\n");
    else
        printf("RESULT: FAIL (%d checks)\n", failures);
    return failures == 0 ? 0 : 1;
}

